import java.io.File;
import java.nio.file.Path;
import java.util.Objects;

public class ImportingUtilities {

    // other methods

    /**
     * Allocates a unique file inside {@code dir} using {@code name} as the base.
     * <p>
     * The method protects against directory‑traversal attacks by normalizing the
     * requested path and ensuring it remains within {@code dir}.  It also strips
     * any query component from {@code name} and guarantees that the returned
     * {@link File} does not already exist, appending a numeric suffix if
     * necessary.
     *
     * @param dir  the target directory where the file should be created
     * @param name the desired file name (may contain path separators)
     * @return a {@link File} instance that does not yet exist
     * @throws NullPointerException     if {@code dir} or {@code name} is {@code null}
     * @throws IllegalArgumentException if the resolved path escapes {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        Objects.requireNonNull(dir, "dir cannot be null");
        Objects.requireNonNull(name, "name cannot be null");

        // Remove any query string that might have been appended to the name
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Resolve the requested path against the target directory and normalize it
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path filePath = dirPath.resolve(name).normalize();

        // Ensure the resolved path is still inside the target directory
        if (!filePath.startsWith(dirPath)) {
            throw new IllegalArgumentException(
                "Attempt to create file outside of target directory: " + name);
        }

        File file = filePath.toFile();

        // Prepare prefix/suffix for generating a unique filename if needed
        int dot = name.indexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Create any missing parent directories
        file.getParentFile().mkdirs();

        return file;
    }

    // other methods

}
```

