     * signature verification.  The list can be extended as needed, but
     * it must never contain "none" or any weak algorithms. */
    private static final Set<String> SUPPORTED_ALGORITHMS =
            Collections.unmodifiableSet(new HashSet<>(
                    java.util.Arrays.asList(
                            "HS256", "HS384", "HS512",
                            "RS256", "RS384", "RS512",
                            "ES256", "ES384", "ES512"
                    )));

