    private JWT decode(String encodedJWT, Header header, String[] parts, Verifier verifier) {

        /* Reject tokens that declare the "none" algorithm.  Allowing
         * unsigned tokens would bypass all signature checks and is
         * a serious security flaw. */
        String algName = header.algorithm.getName();
        if ("none".equalsIgnoreCase(algName)) {
            throw new MissingVerifierException(
                    "Unsigned JWTs are not permitted (algorithm 'none').");
        }

        /* Ensure the algorithm is one of the supported, secure options. */
        if (!SUPPORTED_ALGORITHMS.contains(algName)) {
            throw new InvalidJWTSignatureException(
                    "Unsupported JWT algorithm: " + algName);
        }

        /* If a signature is present, a verifier must also be supplied. */
        if (parts.length == 3 && verifier == null) {
            throw new MissingVerifierException(
                    "No Verifier has been provided for verify a signature signed using [" + algName + "]");
        }

        /* If a verifier is supplied but the token contains no signature,
         * treat it as an invalid signature. */
        if (parts.length == 2 && verifier != null) {
            throw new InvalidJWTSignatureException();
        }

        /* The message comprises the first two segments of the entire JWT,
         * the signature is the last segment. */
        int index = encodedJWT.lastIndexOf(".");
