import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;

class RgbeInfo implements Closeable {

    private final InputStream in;

    // other methods

    /**
     * Decompresses data from the given {@link InputStream} into the supplied
     * output buffer using the Rgbe run‑length encoding scheme.
     *
     * <p>This implementation performs rigorous validation of the input stream
     * to guard against malformed data that could otherwise cause an infinite
     * loop or buffer overrun.  Any deviation from the expected format results
     * in an {@link IOException} being thrown.</p>
     *
     * @param in  the source stream containing compressed data
     * @param out the destination buffer to receive decompressed bytes
     * @throws IOException if the stream ends unexpectedly or contains
     *                     invalid run‑length values
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            final int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading run-length header");
            }

            // A count of zero is not valid in the Rgbe format and would
            // otherwise result in an infinite loop.
            if (n == 0) {
                throw new IOException("Invalid Rgbe run-length encoding: zero count encountered");
            }

            final int remaining = total - position;

            if (n > 128) {
                // Run‑length packet: repeat the following byte (n & 0x7F) times
                final int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading repeated byte");
                }

                final int repeatCount = n & 0x7F;
                if (repeatCount > remaining) {
                    throw new IOException("Run-length exceeds output buffer capacity");
                }

                Arrays.fill(out, position, position + repeatCount, (byte) value);
                position += repeatCount;
            } else {
                // Literal packet: copy the next n bytes verbatim
                if (n > remaining) {
                    throw new IOException("Literal packet exceeds output buffer capacity");
                }

                for (int i = 0; i < n; i++) {
                    final int b = in.read();
                    if (b == -1) {
                        throw new EOFException("Unexpected end of stream while reading literal bytes");
                    }
                    out[position++] = (byte) b;
                }
            }
        }
    }

    // other methods

    @Override
    public void close() throws IOException {
        in.close();
    }
}
