import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely extracts entries from the supplied archive into {@code targetDirectory}.
     *
     * <p>All entry names are validated to prevent path‑traversal attacks. The method rejects
     * absolute paths, names containing {@code ..} components, and any entry that would
     * resolve outside the target directory after canonicalisation.</p>
     *
     * @param supplier      provides the next readable entry
     * @param writer        writes the entry data to an output stream
     * @param targetDirectory the directory into which entries are extracted
     * @throws IOException if an I/O error occurs or a malicious entry is detected
     */
    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the canonical path of the target directory once.
        Path targetPath = targetDirectory.toPath().toRealPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {

            String entryName = nextEntry.getName();
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("archive entry has empty name");
            }

            // Reject absolute paths and names that contain '..' components.
            Path entryPath = Paths.get(entryName).normalize();
            if (entryPath.isAbsolute() || entryPath.startsWith("..")) {
                throw new IOException(
                        "archive entry name '" + entryName + "' is not allowed");
            }

            // Resolve the destination path and ensure it stays within the target directory.
            Path destPath = targetPath.resolve(entryPath).normalize();
            if (!destPath.startsWith(targetPath)) {
                throw new IOException(
                        "expanding " + entryName + " would create file outside of "
                                + targetDirectory);
            }

            File destFile = destPath.toFile();

            if (nextEntry.isDirectory()) {
                if (!destFile.isDirectory() && !destFile.mkdirs()) {
                    throw new IOException("failed to create directory " + destFile);
                }
            } else {
                // Ensure parent directories exist.
                Path parentPath = destPath.getParent();
                if (parentPath != null) {
                    Files.createDirectories(parentPath);
                }

                try (OutputStream out = Files.newOutputStream(destPath)) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
